:root {
  --bg: #0f172a;
  --panel: #1e293b;
  --panel-2: #273449;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --accent: #38bdf8;
  --accent-2: #0ea5e9;
  --danger: #f87171;
  --border: #334155;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

header {
  padding: 2rem 1.5rem 1rem;
  text-align: center;
}
header h1 { margin: 0; font-size: 2rem; }
.subtitle { margin: 0.25rem 0 0; color: var(--muted); }

main {
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 1.5rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 1rem 1.5rem 3rem;
}
@media (max-width: 780px) {
  main { grid-template-columns: 1fr; }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
}
.panel h2 { margin-top: 0; font-size: 1.15rem; }

.form-panel { align-self: start; position: sticky; top: 1rem; }

form label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.85rem;
}
input, textarea {
  width: 100%;
  margin-top: 0.3rem;
  padding: 0.55rem 0.7rem;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.95rem;
}
input:focus, textarea:focus { outline: 2px solid var(--accent); border-color: transparent; }

.form-actions { display: flex; gap: 0.5rem; }
button {
  padding: 0.55rem 1rem;
  border: none;
  border-radius: 8px;
  background: var(--accent-2);
  color: #06283d;
  font-weight: 600;
  cursor: pointer;
  font-size: 0.95rem;
}
button:hover { background: var(--accent); }
button.secondary { background: transparent; color: var(--muted); border: 1px solid var(--border); }
button.secondary:hover { color: var(--text); }

.list-header { display: flex; align-items: center; gap: 1rem; margin-bottom: 0.75rem; }
.list-header input { flex: 1; }
.count { color: var(--muted); font-size: 0.85rem; white-space: nowrap; }

.tag-filters { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-bottom: 1rem; }
.tag-chip {
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--muted);
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  font-size: 0.8rem;
  cursor: pointer;
}
.tag-chip.active { background: var(--accent-2); color: #06283d; border-color: transparent; }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.75rem; }
.bookmark {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.85rem 1rem;
}
.bookmark-title { font-weight: 600; font-size: 1rem; }
.bookmark-title a { color: var(--accent); text-decoration: none; }
.bookmark-title a:hover { text-decoration: underline; }
.bookmark-url { color: var(--muted); font-size: 0.8rem; word-break: break-all; }
.bookmark-desc { margin: 0.4rem 0 0; font-size: 0.9rem; }
.bookmark-tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.5rem; }
.bookmark-tags .tag {
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent);
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  font-size: 0.75rem;
}
.bookmark-actions { display: flex; gap: 0.5rem; margin-top: 0.6rem; }
.bookmark-actions button { padding: 0.3rem 0.7rem; font-size: 0.8rem; }
.bookmark-actions .del { background: transparent; color: var(--danger); border: 1px solid var(--border); }
.bookmark-actions .del:hover { background: rgba(248, 113, 113, 0.15); }
.bookmark-actions .edit { background: transparent; color: var(--muted); border: 1px solid var(--border); }
.bookmark-actions .edit:hover { color: var(--text); }

.empty { text-align: center; color: var(--muted); padding: 2rem 0; }

